ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["radio_14"] = {
{"r8_hor_scanner_repeats_ninth","caller_story_horror",20,300,1,5,1,{"Dee","You're on with me - Marty's not here tonight - what have you got?","Talmadge","I run a scanner, sheriff's band, fire band, all of it, there ain't been a live call on it in a long while","Dee","No, there hasn't","Talmadge","About two in the morning it goes off, dispatch calling a unit out to an address on the Rosewood road","Talmadge","Same call, same words, same voice, same little cough she does - I've got it near by heart","Dee","Which night?","Talmadge","Every night, and the call's from the ninth - I know that because I heard it live the night it happened","Dee","A tape loop somewhere with power to it, that's what I'd want it to be","Talmadge","Me too, except the unit answers her now, it didn't answer her on the ninth - that's how the boy died"}},
{"r8_hor_doors_shut_no_smoke","caller_story_horror",20,300,23,5,1,{"Woodrow","Went through a little place up toward Ekron, twenty houses, maybe twenty-two","Dee","Was anybody there?","Woodrow","Every door shut, front and back, that's the first thing I noticed, 'cause doors don't stay shut, somebody's always gone through 'em","Woodrow","Not one chimney going, not a stovepipe, not a fire ring in a yard","Dee","That doesn't sound strange in July","Woodrow","It was cold that morning - come a front through in the night, I had a coat on, and it stayed cold till nine","Woodrow","Cold enough you'd light something - anybody would, you'd want coffee if nothing else","Dee","So there was nobody","Woodrow","Then who shut the doors? I stood in that road and asked myself that and I got in the truck and I didn't knock on a one of 'em"}},
{"r8_sad_last_jar_her_hand","caller_story_sad",20,300,19,1,1,{"June","Go ahead","Estill","I'm eating the last of my wife's canning","June","How much is left?","Estill","One jar - green beans, ninety-two, it says, she wrote the year on the lid in a grease pencil, every jar, and the month","Estill","Her hand on the lid, that's the thing, there's not another piece of her handwriting in this house, she wasn't much for writing","June","So you haven't opened it","Estill","It's been on the counter nine days, I keep moving it back and forth from the counter to the shelf like I'm working on something","June","Do you have other food?","Estill","I've got plenty, that ain't it and I don't want anybody bringing me nothing","Estill","My daughter in law says take the lid off and keep the lid - which is smart, that's a smart woman","Estill","I'll get to it, sometime this week I'll get to it, and I'd rather not talk about it after tonight if that's all right"}},
{"exp_haircut_mirror","caller_joke",21,3650,0,23,1,{"Lou","A man once asked me to make him look ten years younger","June","That's asking a lot of a haircut","Lou","I asked if he'd accept looking well rested","June","A sensible compromise","Lou","He said he wanted his money's worth","June","What did you do?","Lou","Turned the chair away from the mirror for a while","June","Temporary youth, sold by the minute"}},
{"exp_saved_string","caller_joke",21,3650,0,23,1,{"Mack","Roy's got a collection of pieces of string too short to tie anything","Roy","You could tie them together","Mack","And make a longer piece with thirty knots","Roy","Exactly, now you've understood the collection","Mack","What do you intend to use it for?","Roy","Whatever needs thirty knots","Mack","I don't know how to argue with that","June","I believe the string has won on a technicality"}},
{"exp_bad_magic","caller_joke",21,3650,0,23,1,{"Neal","I knew one card trick, only worked if the other person was very patient","June","What happened if they weren't?","Neal","They'd tell me where I'd put their card","June","That rather defeats the mystery","Neal","Tried it on my nephew, he demanded a refund","June","Had you charged him?","Neal","No, he said his afternoon had value","June","A difficult audience with a promising future in business"}},
{"exp_late_laughter","caller_joke",21,3650,22,5,1,{"Bess","Used to charge extra for breakfast after midnight","June","What changed about the breakfast?","Bess","My willingness to cook it","June","An honest pricing policy","Bess","Men would argue that eggs didn't know what time it was","June","A difficult point to dispute","Bess","I'd tell them the eggs weren't making the bill","June","I hope somebody tipped you for the explanation"}},
{"exp_waking_name","caller_story_sad",21,3650,0,6,1,{"Paula","I wake up halfway through saying somebody's name","June","You don't have to tell us whose","Paula","Some of the dreams are good ones, that's the worst of it","June","The waking up, then?","Paula","For one second I'm just annoyed it's morning","Paula","Then everything else gets back into the room","June","I'm glad you found a voice to answer tonight","Paula","Me too, I wasn't ready to finish that name by myself"}},
{"exp_raider_argument","caller_story_horror",21,3650,0,23,1,{"Low Voice","You told them you were in charge?","Rough Voice","Someone had to sound certain","Low Voice","You aren't in charge of a damn thing","Rough Voice","They didn't know that","Low Voice","People are going to remember what you said","Rough Voice","Good, better than not remembering me at all","Low Voice","Your transmitter's live, you fool","Rough Voice","Then somebody else heard it too"}},
{"exp_club_emptyseat","caller_story_sad",21,3650,0,23,1,{"Duke","Had a man in the club who never shut up about his carburetor","Red","Never shut up about anything, really","Duke","I'd give him a hard time just to change the subject","Red","He knew you weren't serious","Duke","Hope so, I wasn't always good at letting people know","Red","He kept coming back to talk to you","Duke","That's true, even when there were other chairs","Red","Take that for what it was"}},
{"exp_prison_library","caller_story_sad",21,3650,0,23,1,{"Vic","Read the last page of a library book so often it came loose","June","You liked the ending?","Vic","Didn't want to reach it, kept checking how much was left","June","Was it the only book you had?","Vic","No, just the one I cared about at the time","June","Do you remember the title?","Vic","I remember the coffee stain over the last sentence better","Vic","Somebody else's ordinary morning, stuck in there with mine"}},
{"exp_teacher_redpen","caller_story_sad",21,3650,0,23,1,{"Edith","I taught handwriting, still notice how people hold a pencil","June","Hard habit to put down","Edith","My hands want to straighten a page when I see one crooked","June","What do you miss about teaching?","Edith","A child realizing a word on paper belonged to them","Edith","They'd write it on everything - name first, then whatever they loved","June","That's something worth holding on to","Edith","I still have a red pen, been trying to find something to praise with it"}},
{"r2_d21_marty_two_voices_left","military",21,28,0,4,1,{"Marty","It's Marty - it's late - Dee's asleep on the feed sacks, so I'm keeping my voice down","Marty","I used to follow six or seven Army voices on this scanner at once - tonight there are two, the bridge, and a sergeant who reads the weather every morning to nobody in particular","Marty","He gives the clouds, the wind, the temperature, then he says no change to the line - then he signs off","Marty","I've started writing his weather down, it's more reliable than mine","Marty","My eyes won't stay open, I'll leave the scanner playing into the microphone for a while - if you hear snoring, that's me and not the Army"}},
{"r8_sad_winding_the_clock","caller_story_sad",21,320,21,3,1,{"June","Go ahead, you're on","Woodrow","I wind my father's clock Sunday nights, mantel clock, eight day, you turn it seven and a half times and no more","June","Seven and a half","Woodrow","He'd have told you the same, he'd say don't you wind it to the stop, and I'd say yes sir, and I'd have wound it to the stop if he wasn't standing there","June","How long have you had it?","Woodrow","Since eighty-six, I've wound it every Sunday since eighty-six and I've not missed but twice, and one of them was a funeral","June","Have you missed one lately?","Woodrow","That's the thing - Sunday come and I was hauling water and it got dark and I laid down and I never done it","Woodrow","It quit Wednesday, whole house went a different kind of quiet","June","Have you wound it back up?","Woodrow","Not yet, I don't want to set the hands wrong - it's the setting the hands that's got me, I don't know what time it is and it's his clock"}},
{"r9_joke_d21_shower_caps","caller_joke",21,80,16,22,1,{"Caller - Ottis","Marty, I'd like to report that I am the richest man in Knox County","Marty","Go right ahead","Caller - Ottis","In eighty-seven the beauty supply in Elizabethtown went under and I bought their whole stock of shower caps at a nickel a box - my wife has asked me about it every year since","Marty","How much is a whole stock?","Caller - Ottis","Four hundred boxes, they're in the smokehouse","Marty","What on earth does a man do with four hundred boxes of shower caps","Caller - Ottis","They're clean, they're waterproof and they stretch - put one over a jar and it'll hold - put one over a hand you've cut and it'll hold - put four of them over your boots and walk through a creek","Caller - Ottis","I'll send a box home with anybody that asks, and I would like it read on this radio that my wife was wrong","Marty","The wife was wrong, nineteen eighty-seven, vindicated - Ottis, where do you live?"}},
{"r2_d22_silence_nobody_left","military",22,26,0,23,1,{"Warden-6","All Warden stations, this is Warden-6, listening silence remains in effect, report contact and medical only, over","Warden-6","Acknowledge in order - Anvil, over","Warden-6","Hatchet, over","Hatchet-7","Hatchet-7 - acknowledged, over","Warden-6","Crowbar - Striker - Lockbox, over","Lockbox-1-2","Lockbox-1-2 acknowledges - Sir, it's only me and Dunn at the bridge now - the tape does most of the talking, over","Warden-6","Roger, Lockbox - Hatchet-7, where is your commander, over?","Hatchet-7","Sir, you ordered silence, I'd send it by runner - I don't have a runner, so I'll keep it silent, over","Warden-6","Understood - Warden-6, out"}},
{"r3_sf_d22_pillow_turned","sign_off",22,30,0,2,1,{"Dee","I'm going to end early, I had a call on nineteen tonight I couldn't help - I'm not going to tell you about it","Dee","I'll tell you this much, the woman on the other end said thank you at the end - for nothing, for staying on","Dee","People said thank you on my hall, too, right up to the end, they'd say it - for a sip of water, for a pillow turned over to the cool side","Dee","I'm going to go turn my own pillow over - good night"}},
{"r3_sil_d22_mower_belt","silence",22,30,6,10,1,{"Marty","We were off the air all day yesterday, and some of you walked over to see if we were dead - we are not","Marty","The generator threw its belt, and the only spare I had was a belt off a riding mower that fits as long as you don't look at it","Dee","Don't look at it"}},
{"r9_host_d22_walked_fourteen_miles","host",22,55,0,23,1,{"Marty","A man walked here from the far side of Riverside to find out whether there was really anybody in this building","Marty","Fourteen miles, three days, with a gallon jug and a claw hammer - got to the lot, stood out there a while looking at it, then knocked on the glass like it was a Tuesday afternoon","Dee","He asked if he could hear himself, so we let him say his name into it and Marty showed him the needle move","Marty","His name's Willard, he's in my one good chair with a warm Ale-8 and he says he's in no hurry at all to get up out of it","Caller - Willard","I thought it was a tape, three days I walked thinking I was walking to a tape","Marty","Nope, just a man in a feed store with a cat asleep on the transmitter"}},
{"r2_d23_hollis_warning_shots","military",23,23,8,12,3,{"Reverend Hollis","A young soldier walked up the Ekron road Thursday and knocked on the church door - he wanted to know whether God keeps count of warning shots","Reverend Hollis","I asked what he meant, he said, sir, I fired a lot of them first - before the other ones, I want that written down somewhere","Reverend Hollis","So I wrote it down, it's in the front of the pulpit Bible, in pencil, because I didn't know what else a person does with that","Reverend Hollis","He ate two bowls of beans, slept four hours on a pew, and walked back to the line before light - he didn't give me a name, he gave me a callsign","Reverend Hollis","I won't say it on the air, but son, if you're listening, it's written down, the warning shots too"}},
{"r3_so_d23_hollis_otter_creek","sign_on",23,23,6,8,8,{"Reverend Hollis","Good morning, this is Walter Hollis, on the radio at the feed store again - it's Sunday, the first day of August","Reverend Hollis","Last Sunday a young man walked me home, and we got to talking, and it turns out I baptized his daddy in Otter Creek in nineteen and fifty-eight","Reverend Hollis","He said his daddy always told it that I nearly drowned him - I did not nearly drown him, he came up spitting, is all","Reverend Hollis","His daddy's gone now, but the boy's here, and he walked an old man four miles home in the heat, so I'd say the baptism took","Marty","Reverend Hollis will be with us until noon","Reverend Hollis","Or until Marty's second chair gives out, whichever comes first"}},
{"r3_host_d23_hollis_the_ham","host",23,23,9,12,8,{"Reverend Hollis","Somebody on the CB asked Marty to ask me if God did this - I've been asked that about every hard thing for forty years","Reverend Hollis","Tornadoes - cancer, the wrecks out on the Dixie Highway every Christmas","Reverend Hollis","And I'll tell you what I told the mothers, I don't know, I've never known - anybody who tells you they know for sure, check your pockets after they leave","Reverend Hollis","What I do know is who showed up - every time, somebody brought a ham - somebody mowed the yard without being asked, this week, somebody walked four miles to put diesel in Marty's generator","Reverend Hollis","I have never once been able to tell you where the hard thing came from - I can nearly always tell you where the ham came from","Marty","Thank you, Reverend"}},
{"r5_obit_hollis_first_of_august","obituary",23,23,8,12,8,{"Reverend Hollis","Good morning, Knox County, it's the first day of August, and it's Sunday, and I'm glad to have heard from you this week, even those of you who only wrote","Reverend Hollis","Somebody slid a note under the church door asking whether God is punishing us - I'll answer honestly, I don't know, I don't believe so, I've buried too many good people this month to believe so","Reverend Hollis","Here are this week's names","Reverend Hollis","Mae Willoughby, of Irvington, she was the first one at every grieving house with a casserole and the last one out of the kitchen","Reverend Hollis","Dennis Perkins, sixteen, of Muldraugh, he was bagging groceries on the ninth and walked two old women out to their cars, one at a time - his mother asked me to say he was a good boy","Reverend Hollis","Harlan and Iva Beasley, of Fallas Lake, married fifty-two years - their son says they were found together, and he wanted the county to know that","Reverend Hollis","If you have nobody to say your person's name to, send it to me - I'll read it, that's all I can do, and I'll do it every week"}},
{"r9_mb_d23_parts_book","music_bridge",23,80,0,23,1,{"Marty","Right about here is where I'd play you something, I've got no records in this building, so I'm going to read a man some part numbers instead, because he asked me to","Marty","This is for Hershel out toward Irvington, who has got a tractor down and a parts book that's missing the page - get your pencil, I'll go slow","Marty","Fuel filter, three, one, four, eight, dash, seven - water pump gasket, two, nine, oh, three, the little seal that goes behind it, two, nine, oh, four","Marty","Now, none of those numbers will get you a part - there's nobody to hand them to, but if you find a tractor in a field you'll know whether it's got your seal in it","Marty","Hershel, that's your page, I'll read it again Thursday for anybody that missed it, and in the meantime that's your music"}},
{"r2_d25_weather_put_out_pots","military",24,30,5,8,1,{"Hatchet-7","All stations, Hatchet-7, weather for {weekday}, clouds building in the southwest - rain by the afternoon, heavy at times, over","Hatchet-7","Put out every pot and tarp you've got, it's the first real rain in eleven days, no change to the line, over","Hatchet-7","Striker-12, if you're still up at the overpass, the fire dispatcher asked me to tell you she's still there - Hatchet-7, out"}},
{"r3_host_d24_bread_sacks","host",24,30,19,23,3,{"Caller - Anthony","Breaker one-nine, my name's Anthony - I walked out of Louisville, took me nine days - I'm calling because you keep saying 'Louisville direction' like it's still a direction","Marty","Go ahead, Anthony","Caller - Anthony","It's not a city anymore, I won't tell you what it is - people on the road keep asking me whether their street's alright, and I keep telling them I didn't go down their street","Caller - Anthony","I only want to say one thing, to anybody waiting on somebody from up there - I got out, it took nine days, and I got out, so don't quit waiting on my account","Marty","Thank you, Anthony - I, uh - thank you","Dee","Anthony, this is Dee, the nurse - are you hurt?","Caller - Anthony","My feet - that's all, wore through my shoes the fourth day, I've got bread sacks tied over my socks","Dee","Come to the feed store in daylight, there are work boots on the wall - they're for farmers, they'll fit you better than bread sacks"}},
{"r3_ins_d24_shifts","instruction",24,30,5,9,1,{"Dee","I'm going to talk about sleep, because I can hear it in your voices on nineteen - everybody's running on fumes","Dee","If there's more than one of you, take shifts, two hours awake, four asleep, whoever's awake sits up - not lies down, lying down awake turns into asleep","Dee","Keep the one on watch busy with their hands - Darn a sock, clean a rifle, snap beans, busy hands keep eyes open","Dee","If you're by yourself, sleep days in the most closed-up room you have, and be up at night, when you'd want to be awake to hear something anyway","Dee","Night nurse's rules, black out the room, eat your breakfast before bed, and don't argue with your body about what time it is - you'll lose"}},
{"r3_sil_d24_three_barks","silence",24,30,1,4,1,{"99.6 FM","(The carrier hums, a cat walks across something papery - far off, a dog barks three times and stops)"}},
{"r9_ins_d24_boots_and_feet","instruction",24,90,8,20,1,{"Marty","Feet, you're walking more than you have in your whole life, and a foot will put you down as sure as anything else out there will","Marty","Two pair of socks if you own two pair, change at noon - hang the wet pair off your pack and put the dry ones on dry feet - wipe your feet with your shirt tail if that's all you've got","Marty","Do not dry boots at the fire, you'll cook the leather stiff and then it'll cut you - stuff them with newspaper and set them near it, not at it","Dee","White, wrinkled and numb after a wet day is the start of something - warm them slow, get them dry, and don't rub them","Dee","And cut your toenails straight across, I have lanced two toes this month for a man who was cutting corners on a corner","Marty","A blister you covered is a blister, a blister you walked ten more miles on is a month sat in a chair"}},
{"more_radio_road_king","caller_joke",25,3650,0,23,1,{"Unknown","He wants us to call him the road king","Second Voice","Hey, quieter, he's standing right there","Unknown","King of what? Two cones and a busted lawn chair?","Second Voice","Three cones","Unknown","THREE cones, well, shit, give him a crown","Second Voice","You're on the radio","Unknown","I'm not press-- oh, fuck","Second Voice","You absolutely are","Unknown","Boss? If that's you, we're, uh... we found your cone","Second Voice","Put the damn microphone down"}},
{"r3_so_d25_station_improvements","sign_on",25,30,5,8,1,{"Marty","Good morning, this is ninety-nine point six, and I'm pleased to announce some improvements to the station","Marty","We now have a second chair, the second chair has all four legs, we also have a box fan, which runs when the generator runs, which is when I'm talking - so you've got me to thank for Dee not melting","Dee","He's taking credit for a fan","Marty","Somebody has to, also improved, the roof over the back office no longer drips on the transmitter, thanks to a family from Riverside who traded a sheet of tin for two sacks of oats","Marty","What has not improved is anything else - it's {time} - count your people"}},
{"r3_host_d25_notes_changed","host",25,30,0,23,1,{"Marty","The mail slot's still getting notes, but they've changed, three weeks ago it was 'Have you seen.' Now it's 'I have'","Marty","'Have a milk goat, need a goat man' - and 'Two boys, fourteen and sixteen, need a fence'","Marty","I've read that last one four times this morning","Marty","That ain't no trade, that's a mother asking for help - if you've got a fence and room for two more at the table, her name is Carla, and she checks the slot on Tuesdays"}},
{"r3_wx_d25_dog_days","weather",25,30,5,10,1,{"Marty","These are the dog days, the old folks said they come when the Dog Star rises with the sun, and they mean the creeks go low and cuts heal slow","Marty","The creek behind the store is down to where you can see the rocks - if you draw water from a creek, draw it where it's moving, not from the still pools - then boil it anyway","Marty","High of ninety-three, no rain coming that my knee knows about","Dee","Old folks were right, cuts heal slow in this heat - wash 'em, dry 'em, and come find me if they go red","Marty","They also said snakes go blind in the dog days and strike at anything - I don't know about that - watch where you put your feet either way"}},
{"r5_joke_hank_six_apples","caller_joke",25,120,17,22,1,{"Caller - Hank","Dee, my mamaw always said an apple a day keeps the doctor away","Dee","Did she, Hank","Caller - Hank","I found an old orchard up past Ekron, I've been eating six a day","Dee","Hank, I'm about the only medical person you can reach in this county, and you're out there trying to keep me away","Caller - Hank","No ma'am, that's a side effect","Dee","Six apples a day has a side effect, Hank, and I am not describing it on the radio"}},
{"r5_host_rain_stock_trough","host",25,70,0,23,1,{"Marty","That racket is rain on the tin roof, the first real rain in weeks - I apologize to anybody straining to hear us","Dee","I put every pot we own out on the loading dock - Marty dragged out a stock trough","Marty","It holds a hundred gallons, I'm a professional","Dee","It also held a whole summer of pigeon business before the rain came","Marty","We'll boil that one twice","Dee","We'll boil that one never, everybody, catch your rain off something clean, and boil it anyway"}},
{"r5_trade_reading_glasses_faye","trade",25,250,9,16,1,{"Caller - Faye","Marty, I was the receptionist at the eye doctor in West Point - I've got a box of reading glasses out of the back room - near about two hundred pair","Marty","Faye, I believe you just became the most important person in Knox County","Caller - Faye","They're all different strengths, plus one up to plus three and a half - bring something to read and try them till the words sit still","Marty","What do you want for them?","Caller - Faye","Canned fruit, if you've got it, if you don't, come anyway - nobody should have to guess which pill bottle is which","Marty","Where, Faye?","Caller - Faye","The front steps of the West Point library, at noon - I'll be the one with the box and the big straw hat","Marty","West Point library steps, noon - Faye, I'll be in that line myself, I've been holding my notes at arm's length for a month"}},
{"r5_joke_curtis_numbers","caller_joke",25,250,18,22,1,{"Caller - Curtis","Marty, I made up my mind back in July to read the whole Bible, cover to cover","Marty","How far have you got, Curtis?","Caller - Curtis","Numbers","Marty","That's slow going","Caller - Curtis","It's mostly counting, whose family, how many, where they set up camp","Caller - Curtis","I'm in no hurry, it's the only book left in this county where everybody's still accounted for"}},
{"r5_host_tomato_feud_riverside","host",25,90,0,23,1,{"Marty","We've had four calls tonight about tomatoes, and I'd like the two gentlemen in Riverside to know this station is neutral","Dee","The station is not neutral, the station has eaten one of Mr. Lyle's tomatoes, and they are better","Marty","The station is neutral in public","Dee","Mr. Hanley, your peppers are very nice, we're sorry about the tomatoes","Marty","And that is how you lose every listener on one side of a street in Riverside"}},
{"r9_host_d26_boy_on_a_bicycle_mail","host",26,75,0,23,1,{"Marty","This county has got a mail service, I want to be careful how I say this, because the mail service is a fourteen year old boy on a ten speed bicycle","Marty","His mother called me first and made me promise I'd read her rules on the air before I said his name - so these are hers, not mine","Marty","He rides in daylight, he does not go inside a house, he does not go anywhere he can't see both ways down the road - and if your dog runs loose, tie your dog","Dee","And nobody puts anything in his bag heavier than paper - he's carrying notes, he is not carrying your cans","Marty","His name's Tilford and he's been to Ekron and back twice this week - notes go in the mail slot here and he sorts them on my counter with the concentration of a bank teller"}},
{"r2_d27_task_force_inactivated","military",27,30,18,23,2,{"Warden-6","All Warden stations, this is Warden-6, by order of higher headquarters, Task Force Warden is inactivated effective 2359 tonight, over","Warden-6","Personnel inside the line remain inside the line, the line is held from the outside now - stations inside will receive no further orders from this headquarters, over","Hatchet-7","Warden-6, Hatchet-7 - request clarification - who do we work for after 2359, over?","Warden-6","Stand by","Warden-6","Hatchet-7, I have no answer to give you, do what you'd do if you had one - that's my last order, over","Lockbox-1-2","Warden-6, Lockbox-1-2 - does the tape at the bridge keep playing, over?","Warden-6","Nobody has told me to turn it off - Warden-6, out"}},
{"r2_d28_dee_after_last_order","military",28,30,7,12,1,{"Dee","Marty's asked me to take this one, he listened to that last Army order three times, and then he went out to sit on the loading dock","Dee","So, plainly, the task force that ran the checkpoints says it doesn't exist after last night - the soldiers who were inside the line are still inside, same as us","Dee","That means some of them will come to your door - most will be hungry kids in uniform, a few will have figured out that a rifle gets them whatever they point it at","Dee","You can't tell which by the uniform, talk through the door first - ask them when they last ate, how they answer tells you plenty","Dee","Marty's back, red-eyed, blames feed dust - and I've been in this store three weeks, no feed anywhere"}},
{"r3_host_d28_police_log","host",28,30,20,23,1,{"Marty","Dee's taking over in a minute, before she does, somebody on nineteen asked what I miss most - I've been chewing on it all day","Dee","He's been pacing","Marty","I thought it'd be air conditioning, or ice, it's the newspaper - the Thursday paper, with the grocery ads and the ball scores and who got married","Marty","I used to read the sheriff's log out loud to Nancy - 'loose cow on Hollow Road.' 'Man reports neighbor's music too loud.' We'd laugh at that","Marty","I'd give a good deal for a loose cow on Hollow Road to be the worst thing in the paper","Dee","I miss my old charge nurse, she was awful, I would give a week's pay to hear that woman tell me I charted something wrong","Marty","And on that, here's Dee - go easy on her, she's in a mood about a charge nurse"}},
{"r9_trade_d28_two_arms_only","trade",28,85,9,16,1,{"Caller - Bascom","Marty, I've got nothing to trade, I want that said first so nobody wastes the gas driving out here","Marty","Go ahead and say it, then","Caller - Bascom","I'm thirty-four and I'm strong and I'll work - dig, haul, stack, shovel, roof, tear down, whatever it is - I'll work a day for supper and a place on a floor","Marty","And before all this, what'd you do?","Caller - Bascom","Loaded trucks out at the distribution center eleven years, I'm good at carrying things and doing what I'm told, and I'd be lying to you if I said I was good at much else","Dee","Bascom - are you eating?","Caller - Bascom","I'm all right","Marty","He's not, folks, if you've got two days of work and a plate, that's the trade - out front of the Ekron fire hall, in the daylight - and Bascom, you come by here after, and we'll talk about all right"}},
{"r9_joke_d29_rooster_alarm","caller_joke",29,100,16,22,1,{"Caller - Mozelle","Marty, I have fought with my neighbor about his rooster for nine years - nine years of that bird","Marty","And how's the war going, Miz Mozelle?","Caller - Mozelle","I've surrendered, that rooster is the only clock left on this road and everybody knows it","Caller - Mozelle","The Hurst girl times her bread by him, the man on the corner gets up and pulls his watch by him - I sat up in bed Tuesday when he didn't go off and I thought, well, something's happened","Marty","Was something wrong with him?","Caller - Mozelle","He'd got in the shed, he was fine and he was furious","Caller - Mozelle","So I want it on the radio that I take back every word - and I fed him out of my hand this morning, and he bit me, and I deserved it"}},
{"r3_sf_d30_hollis_come_back","sign_off",30,30,22,23,8,{"Marty","A storm came up this afternoon, so Reverend Hollis is spending the night on the cot, and I'm on the floor, which he tried to argue about and lost","Reverend Hollis","I lost because I'm old and he's stubborn, and stubborn beats old every time","Reverend Hollis","Before Marty shuts this off, I'll say what I used to say at the church door, shaking hands - go home - eat something - be good to the people in your house - come back next week","Reverend Hollis","That last part's the one that matters - come back next week","Marty","Good night, everybody - count your people"}},
{"r3_host_d30_hollis_sit_down","host",30,30,9,12,8,{"Reverend Hollis","Good morning, third Sunday I've come down to this feed store - Marty says that makes me a regular, at my church, a regular had a pew with his shape worn into it","Reverend Hollis","Mine's a feed sack, it's already got my shape in it","Reverend Hollis","This week three families came out to sleep in the fellowship hall at the church, because it's brick and the windows are up high - we had fourteen on Wednesday night","Reverend Hollis","One of the little ones asked me if church was every night now - I said, well, it is for a while, she said good, because she likes the part where you sit down","Reverend Hollis","Sit down a minute today, if you can, that's the sermon, such as it is"}},
{"r5_host_dee_why_march_ridge","host",30,120,0,23,1,{"Dee","People keep asking why a Muldraugh girl is talking on a March Ridge station","Dee","I walked out of work on the eleventh with a first aid bag, a flashlight, and no plan at all - it took me a week of back roads to get anywhere","Dee","Somewhere in there I heard Marty on a transistor radio in a stranger's glove box - he was reading a list of roads not to take, and he said 'please' before every one","Dee","I figured a man who says please to strangers over the air probably needed a nurse","Marty","I say please because my mother would climb out of her grave and... Well - that's a poor way to put it in this county","Dee","He's turned red, you can't see it, but trust me, everybody, he is red to the ears"}},
{"r5_trade_farrier_wes","trade",30,130,9,16,1,{"Marty","Trading Post - Wes, go ahead","Caller - Wes","Marty, I'm a farrier - Shod horses around Brandenburg for fifteen years, more folks are riding now, with gas being what it is","Caller - Wes","I'll trim and shoe a horse for a gallon of gas, a pound of coffee, or a good hot meal - bring your own shoes if you've got them, I'm running low","Marty","Where do people find you?","Caller - Wes","March Ridge, the feed store loading dock, any morning at eight","Marty","That is my loading dock, Wes","Caller - Wes","I figured you wouldn't mind","Marty","I mind a little - come anyway, I'll put the percolator on"}},
{"r5_host_dee_waiting_room_joke","host",30,200,17,23,1,{"Dee","I've got a joke","Marty","The nurse has a joke, everybody hold onto something","Dee","One of them shambles into the clinic, and the lady at the front desk says, 'Sign in, honey, it'll be about three hours'","Marty","And what does it say?","Dee","Nothing - it's dead, but it sits down and waits the whole three hours without one complaint, which is more than any of you ever managed","Marty","Dee, I wouldn't call that a joke, it's a grudge","Dee","Eleven years of nights, Marty - it's both"}},
{"r5_trade_hearing_aid_lorraine","trade",30,250,9,16,1,{"Caller - Lorraine","Is this the trading show? I can't hear a thing - I've got the radio right up against my ear","Marty","You're on, ma'am - go ahead","Caller - Lorraine","Talk louder, young man, I need batteries for my hearing aid, the little ones - size thirteen, with the orange sticker","Dee","Size thirteen, orange tab, got it, Lorraine","Caller - Lorraine","I've got quilts to trade, three of them, good and heavy, double wedding ring, I made every stitch myself","Marty","Three quilts for hearing aid batteries - where will you meet?","Caller - Lorraine","The side door of the Methodist church in March Ridge, at noon - I'll be on the bench","Marty","Methodist church, side door, noon, folks, check your mamaw's dresser drawer - those little batteries end up everywhere","Caller - Lorraine","What did he say?"}},
{"r5_host_generator_hours","host",30,120,0,23,1,{"Marty","We'll be on the air less for a while, and I'd rather tell you why than just go quiet on you","Dee","It's the generator, it drinks a gallon and a half every four hours, and gas has got hard to come by","Marty","If it were up to me, I'd run it all night","Dee","It isn't only up to you, there's a little fridge in the back with insulin in it for two families who come by","Marty","So the fridge wins, and that's the right call, I just want you to know the quiet isn't us quitting","Dee","Six to nine in the morning, six to nine at night - unless somebody trades us gas","Marty","Which is a hint, about as big a hint as I know how to drop"}},
{"r5_obit_caller_doc_freeman_pie","obituary",30,200,8,21,1,{"Caller - Doyle","Marty, I'd like to have Doc Freeman read, large-animal vet, out of Brandenburg","Marty","Everybody knew Doc Freeman - go ahead, Doyle","Caller - Doyle","Winter of eighty-five, he came out at three in the morning in a snowstorm to pull a calf for my daddy - backwards calf - it lived","Caller - Doyle","Daddy asked what we owed him, and Doc said a pie - Daddy said that's not a real bill - Doc said, 'It is at three in the morning'","Caller - Doyle","We never did make that pie, eight years, and somehow we never did","Caller - Doyle","My wife made it last week - apple, I drove it over and set it on his porch - I don't know what else you do with a bill like that"}},
{"r5_joke_arlene_quilted_sleeves","caller_joke",30,250,17,22,1,{"Caller - Arlene","Marty, the Tuesday quilting circle is down to four ladies, and we've voted to stop making baby quilts","Marty","I'm sorry to hear it, Arlene","Caller - Arlene","Don't be, we make sleeves now, old denim on the outside, quilt batting on the inside, stitched tight, wrist to shoulder","Caller - Arlene","You can't bite through them - we tested","Marty","How do you test a thing like that?","Caller - Arlene","Norma's grandson did it on a dare, he lost a tooth, his mama is not speaking to the quilting circle"}},
{"r5_trade_lester_creek_water","trade",30,200,9,16,1,{"Caller - Lester","I want to warn people, and then I want to say something to the fella who did it","Marty","Go ahead, Lester","Caller - Lester","I traded my wife's sewing machine for twenty gallons of gas - four cans, got home, and it was fifteen gallons of gas and five gallons of creek water","Dee","Everybody, pour a little from every can into a clear jar before you hand anything over - water sinks to the bottom, you'll see the line","Marty","And what did you want to say to him?","Caller - Lester","The sewing machine needs a new belt, it slips on the heavy stuff - I figured he'd want to know","Marty","That's more than he'd have done for you, Lester","Caller - Lester","Well, my wife would have told him - she was particular about that machine"}},
{"r5_obit_caller_lonnie_mowers","obituary",30,250,8,21,1,{"Caller - Donnie","My brother - Lonnie Sizemore, of Echo Creek, I'd like him read","Caller - Donnie","He fixed every lawn mower on our road for twenty years - wouldn't take a dime, he'd bring it back with the blade sharpened and a full tank, and act like he forgot about the gas","Caller - Donnie","Never once fixed his own, his own mower hasn't started since the eighties","Marty","Every road's got a Lonnie","Caller - Donnie","His mower's still in his shed, the carburetor's sitting on a paper towel on the seat, right where he left it","Caller - Donnie","I go out there and look at it - that's all, I just go look at it"}},
{"r5_joke_gil_catfish","caller_joke",30,250,17,22,1,{"Caller - Gil","Marty, I caught a blue catfish off the bank at Brandenburg this morning as long as my truck bed","Marty","Gil, you've called about that catfish three times now, and it's grown a foot every time","Caller - Gil","It's been eating well","Marty","On what?","Caller - Gil","Marty, you don't want to know what's floating in that river these days - I'm just telling you it's a well-fed fish","Dee","And you are not eating it","Caller - Gil","Dee, I'm not even letting it in the truck"}},
{"r5_joke_loretta_bulged_can","caller_joke",30,250,17,22,1,{"Caller - Loretta","Dee, is it safe to eat a can of beans that's bulged out a little?","Dee","No","Caller - Loretta","What about just a little bitty bulge?","Dee","Loretta, no, botulism does not care how polite the bulge is - throw it out where the dogs can't get it","Caller - Loretta","Well, then I'll feed it to my husband","Dee","Loretta!","Caller - Loretta","I'm teasing - mostly, he ate my last chocolate pudding cup and lied about it to my face"}},
{"r5_joke_jolene_mullet","caller_joke",30,250,17,22,1,{"Caller - Jolene","This is Jolene, I did hair at the beauty shop in Muldraugh for fourteen years, and I am open for business","Marty","What does a haircut cost these days, Jolene?","Caller - Jolene","Two cans of anything, and bring your own scissors, mine went missing in July","Caller - Jolene","Now, I'll be honest, my hands shake a little more than they used to","Marty","Only a little?","Caller - Jolene","Only when something groans outside, so you sit still and you pray for quiet, and you'll get a real nice trim","Caller - Jolene","If one of them groans outside while I'm cutting, you're leaving with a mullet"}},
{"r5_trade_kenny_bicycle_parts","trade",30,200,9,16,1,{"Caller - Kenny","Marty, I fixed bicycles out of my garage in Brandenburg - I've got inner tubes, patch kits, brake cables, and a floor pump","Caller - Kenny","Bikes don't need gas, and they don't make noise, everybody ought to have one","Marty","Kenny, I'm fifty-four years old, and my knees would like a word with you","Caller - Kenny","Your knees will thank me by Christmas, I want kerosene, or lamp oil, or a good sharp hatchet","Marty","Where at?","Caller - Kenny","The Brandenburg boat launch, two in the afternoon, I'll ride there - Obviously","Marty","Brandenburg boat launch, two PM, kerosene or a hatchet for bicycle parts - and a lecture, apparently, at no extra charge"}},
{"r5_obit_caller_tommy_lee_fiddle","obituary",30,250,8,21,1,{"Caller - Rusty","Marty, I want to read Tommy Lee Gaines, he played fiddle at the VFW in West Point, second Saturday of every month, for twenty-some years","Caller - Rusty","He knew maybe eleven tunes, played every one of them like he'd just made it up that morning","Caller - Rusty","Taught any kid who'd sit still, and never charged, he said the only payment was they had to play at his funeral","Marty","Did any of them?","Caller - Rusty","There wasn't a funeral, Marty, nobody's getting one","Caller - Rusty","His fiddle's in its case at my house, I can't play a note - every so often I open it up and tighten the strings back, so it's ready for one of those kids"}},
{"r5_joke_buck_bowling_ball","caller_joke",30,300,17,22,1,{"Caller - Buck","Marty, I lost the house to a fire in August - lost my truck in the creek, lost my bass boat to some fella with a rifle","Marty","Buck, that's a hard year","Caller - Buck","You know which one I miss?","Marty","The boat?","Caller - Buck","My bowling ball, sixteen pounds, drilled to fit my hand at the lanes in Elizabethtown - I can't think of one single thing I'd use it for","Caller - Buck","I just want to hold it"}},
{"r5_obit_caller_florence_library_fines","obituary",30,250,8,21,1,{"Caller - Gwen","I want to read Mrs. Florence Tubb, she was the librarian in West Point for as long as I've been alive","Caller - Gwen","If you brought a book back late, she'd waive the fine if you could tell her what happened in it - she'd sit and listen to a whole book report right there at the desk","Caller - Gwen","Kids read entire books just to get out of a dime - she knew exactly what she was doing","Caller - Gwen","I've got a book out on bridges, it was due July twelfth, I owe forty cents","Caller - Gwen","I finished it last week, I keep thinking about what I'd tell her"}},
{"r5_obit_caller_red_cap_riverside_road","obituary",30,300,8,21,1,{"Caller - Jerry","I don't have a name for this one - is that alright?","Marty","It's alright, Jerry - go ahead","Caller - Jerry","On the ninth, my car went in the ditch on the Riverside road, and they were coming across the field - a man in a red ball cap yanked my door open and dragged me out by my collar","Caller - Jerry","He pointed at the tree line and said, 'That way - run.' Then he turned around and walked toward them, waving his arms and hollering","Caller - Jerry","I ran, I never got a good look at his face - just the red cap","Caller - Jerry","Could you put him on the list? Just put down, 'the man in the red cap, on the Riverside road'","Marty","The man in the red cap, on the Riverside road - he's on the list, Jerry"}},
{"r5_trade_dewey_johnboat_radio","trade",30,200,9,16,1,{"Caller - Dewey","Marty, I've got a fourteen-foot johnboat with oars and a pair of life jackets - no motor, quieter that way, anyhow","Marty","What are you after, Dewey?","Caller - Dewey","A radio that pulls in this station clear, mine fades out every time you say anything important","Marty","A boat for a radio?","Caller - Dewey","I don't go on the water anymore, Marty, my wife listens to you all day - she misses half of it and makes me guess what you said","Dee","Dewey, before anybody takes that boat anywhere, the Ohio is not a way out, people have tried - keep to the lakes and the creeks","Caller - Dewey","Fallas Lake, the bait shop dock, nine in the morning - bring the radio with batteries in it, so I can hear it work","Marty","Fallas Lake bait shop dock, nine AM, a johnboat for a radio - and Dewey's wife, I'll try to say the important things twice"}},
{"r5_obit_caller_vince_game_warden","obituary",30,300,8,21,1,{"Caller - Marlene","Marty, I want to read my husband - Vince Ralston, of Rosewood","Marty","Go ahead, Marlene, take your time","Caller - Marlene","Thirty-one years, he told the same joke at every wedding we ever went to - the game warden and the bass, people would see him stand up and start groaning","Caller - Marlene","He did the voices, the warden squeaky as a hinge, heh, and the bass sounded like- well","Caller - Marlene","I can't do it, only he could do the bass","Caller - Marlene","Vince Ralston - that's all, thank you for letting me say it"}},
{"r7_mil_ghost_net_call_nobody","military",30,90,5,8,1,{"Cardinal Main","All Cardinal stations, this is Cardinal Main - net call, report in order, over","Cardinal Main","Cardinal-1-6, over","Cardinal Main","Cardinal-2-6, over","Cardinal Main","Cardinal-3-6, over","Cardinal Main","All stations, nothing heard, net call complete at {time} - Cardinal Main remains on this frequency, over","Cardinal Main","Cardinal Main, out"}},
{"r9_obit_d30_caller_canning_labels","obituary",30,120,8,21,1,{"Caller - Garnett","Marty, I'd like my wife read - Maudie Seay, out on the Echo Creek road","Marty","Go ahead, Garnett, take your time with it","Caller - Garnett","I've got about sixty quarts in the cellar with her writing on them - she put the year and what it was and then a little something - green beans, ninety-one, too much salt, sorry","Caller - Garnett","I've been eating them in the order of how much I like her notes - I started at the far end on purpose","Marty","What's the last one going to be?","Caller - Garnett","Blackberry jam, ninety-two, it says, Garnett do not eat this all at once","Caller - Garnett","I'm eating that whole jar in one sitting, I don't care what it says","Marty","Maudie Seay, of Echo Creek Road - Garnett, you call me the day you open it"}},
{"exp_seed_envelope","caller_story_sad",31,3650,0,23,1,{"Silas","I found myself making a list for next spring","June","Did that surprise you?","Silas","Felt presumptuous, like I ought to ask permission to think that far","June","What went on the list?","Silas","Mostly things I'd done wrong before - spacing, keeping better notes","June","Not a grand plan, then","Silas","No, I'd like the chance to make smaller mistakes","June","That sounds like a future worth writing down"}},
{"exp_new_table_rules","caller_joke",31,3650,0,23,1,{"Kit","Tom proposed rules for conversation at dinner","Tom","One rule - stop describing your feet while people eat","Kit","That's censorship of an important subject","Tom","Your blister does not need a weekly report","Kit","I'm sorry you're opposed to updates","Tom","June, tell her that's reasonable","June","I'd like to keep the station's position on feet unofficial","Kit","Then the debate continues, same time next dinner"}},
{"exp_old_orders","military",31,3650,0,23,1,{"Corporal","Do you still carry the old orders?","Sergeant","Folded up - why?","Corporal","Mine are nearly unreadable at the creases","Sergeant","You remember what they say","Corporal","That's not the same as knowing who still stands behind them","Sergeant","No, it isn't","Corporal","I wanted somebody else to admit that","Sergeant","Then you've got your answer, doesn't make the afternoon simpler"}},
}
